import Link from "next/link";
import { notFound } from "next/navigation";
import { FiArrowLeft } from "react-icons/fi";
import { createClient } from "@/lib/supabase/server";
import { getPlantById } from "@/lib/plants/queries";
import PlantForm from "@/components/plants/PlantForm";
import { updatePlantAction } from "@/lib/plants/actions";

export default async function EditPlantPage({ params }) {
  const { id } = await params;
  const supabase = await createClient();
  const plant = await getPlantById(supabase, id);

  if (!plant) notFound();

  return (
    <div className="space-y-5">
      <Link
        href={`/plants/${plant.id}`}
        className="inline-flex items-center gap-1.5 text-sm text-ink-muted transition hover:text-ink"
      >
        <FiArrowLeft size={15} />
        Back
      </Link>

      <h1 className="text-2xl font-semibold tracking-tight text-ink">
        Edit {plant.nickname}
      </h1>

      <PlantForm
        action={updatePlantAction}
        plant={plant}
        submitLabel="Save changes"
      />
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { FiEdit2, FiArrowLeft } from "react-icons/fi";
import { PiPlantFill } from "react-icons/pi";
import { createClient } from "@/lib/supabase/server";
import { getPlantById } from "@/lib/plants/queries";
import { getCareTasksForPlant } from "@/lib/care-tasks/queries";
import { PLANT_TYPE_LABELS } from "@/lib/constants/plant-types";
import DeletePlantButton from "@/components/plants/DeletePlantButton";
import CareTaskList from "@/components/care-tasks/CareTaskList";

export default async function PlantDetailPage({ params }) {
  const { id } = await params;
  const supabase = await createClient();
  const plant = await getPlantById(supabase, id);

  if (!plant) notFound();

  const tasks = await getCareTasksForPlant(supabase, plant.id);

  return (
    <div className="space-y-6">
      <Link
        href="/plants"
        className="inline-flex items-center gap-1.5 text-sm text-ink-muted transition hover:text-ink"
      >
        <FiArrowLeft size={15} />
        All plants
      </Link>

      <div className="card overflow-hidden">
        <div className="aspect-[4/3] bg-surface-muted">
          {plant.photo_url ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={plant.photo_url}
              alt={plant.nickname}
              className="h-full w-full object-cover"
            />
          ) : (
            <div className="flex h-full w-full items-center justify-center">
              <PiPlantFill size={48} className="text-ink-faint/50" />
            </div>
          )}
        </div>

        <div className="p-5">
          <div className="flex items-start justify-between gap-3">
            <div className="min-w-0">
              <h1 className="truncate text-xl font-semibold tracking-tight text-ink">
                {plant.nickname}
              </h1>
              <p className="mt-0.5 text-sm text-ink-muted">
                {plant.common_name}
                {plant.scientific_name && (
                  <span className="italic text-ink-faint">
                    {plant.common_name ? " · " : ""}
                    {plant.scientific_name}
                  </span>
                )}
              </p>
            </div>
            <span className="pill shrink-0 bg-brand-soft text-brand-soft-ink">
              {PLANT_TYPE_LABELS[plant.plant_type]}
            </span>
          </div>

          {plant.notes && (
            <p className="mt-4 whitespace-pre-wrap border-t border-line pt-4 text-sm text-ink-muted">
              {plant.notes}
            </p>
          )}

          <div className="mt-5 flex gap-2">
            <Link href={`/plants/${plant.id}/edit`} className="btn-secondary !py-2">
              <FiEdit2 size={15} />
              Edit
            </Link>
            <DeletePlantButton plantId={plant.id} />
          </div>
        </div>
      </div>

      <CareTaskList plantId={plant.id} tasks={tasks} />
    </div>
  );
}

import AddPlantWizard from "@/components/plants/AddPlantWizard";

export default function NewPlantPage() {
  return <AddPlantWizard />;
}

import Link from "next/link";
import { FiPlus } from "react-icons/fi";
import { PiPlantFill } from "react-icons/pi";
import { createClient } from "@/lib/supabase/server";
import { getPlantsForUser, getPlantTypeCounts } from "@/lib/plants/queries";
import { isPlantType } from "@/lib/constants/plant-types";
import CategoryTabs from "@/components/plants/CategoryTabs";
import PlantCard from "@/components/plants/PlantCard";

export default async function PlantsPage({ searchParams }) {
  const { type } = await searchParams;
  const activeType = isPlantType(type) ? type : null;

  const supabase = await createClient();
  const [plants, counts] = await Promise.all([
    getPlantsForUser(supabase, { plantType: activeType }),
    getPlantTypeCounts(supabase),
  ]);

  const overdueTotal = plants.reduce((sum, p) => sum + (p.overdue_count ?? 0), 0);

  return (
    <div className="space-y-5">
      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight text-ink">
            Your plants
          </h1>
          <p className="mt-0.5 text-sm text-ink-muted">
            {overdueTotal > 0
              ? `${overdueTotal} task${overdueTotal === 1 ? "" : "s"} need attention`
              : plants.length > 0
                ? "Everything's on schedule"
                : "Let's get your first plant in here"}
          </p>
        </div>
        <Link href="/plants/new" className="btn-primary shrink-0 !px-3.5">
          <FiPlus size={17} />
          <span className="hidden sm:inline">Add plant</span>
        </Link>
      </div>

      <CategoryTabs activeType={activeType} counts={counts} />

      {plants.length === 0 ? (
        <div className="card flex flex-col items-center px-6 py-14 text-center">
          <span className="mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-brand-soft text-brand-soft-ink">
            <PiPlantFill size={26} />
          </span>
          <p className="font-medium text-ink">
            {activeType ? "Nothing in this category" : "No plants yet"}
          </p>
          <p className="mt-1 max-w-xs text-sm text-ink-muted">
            {activeType
              ? "Try another category, or add a new plant."
              : "Take a photo and we'll identify the species and build a care schedule for you."}
          </p>
          {!activeType && (
            <Link href="/plants/new" className="btn-primary mt-5">
              <FiPlus size={17} />
              Add your first plant
            </Link>
          )}
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 sm:gap-4">
          {plants.map((plant) => (
            <PlantCard key={plant.id} plant={plant} />
          ))}
        </div>
      )}
    </div>
  );
}

import { createClient } from "@/lib/supabase/server";
import ReminderSettingsForm from "@/components/settings/ReminderSettingsForm";
import PushToggle from "@/components/settings/PushToggle";

export default async function SettingsPage() {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();

  const { data: profile } = await supabase
    .from("profiles")
    .select("email, display_name, avatar_url, timezone, reminder_hour")
    .eq("id", user.id)
    .single();

  const initial = (profile?.display_name || profile?.email || "?")
    .charAt(0)
    .toUpperCase();

  return (
    <div className="space-y-7">
      <h1 className="text-2xl font-semibold tracking-tight text-ink">Settings</h1>

      <div className="card flex items-center gap-3 p-4">
        {profile?.avatar_url ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={profile.avatar_url}
            alt=""
            className="h-11 w-11 rounded-full object-cover"
          />
        ) : (
          <span className="flex h-11 w-11 items-center justify-center rounded-full bg-brand-soft text-base font-semibold text-brand-soft-ink">
            {initial}
          </span>
        )}
        <div className="min-w-0">
          {profile?.display_name && (
            <p className="truncate text-sm font-medium text-ink">
              {profile.display_name}
            </p>
          )}
          <p className="truncate text-sm text-ink-muted">{profile?.email}</p>
        </div>
      </div>

      <section className="space-y-3">
        <h2 className="text-xs font-semibold uppercase tracking-widest text-ink-faint">
          Notifications
        </h2>
        <PushToggle />
      </section>

      <section className="space-y-3">
        <h2 className="text-xs font-semibold uppercase tracking-widest text-ink-faint">
          Daily digest
        </h2>
        <p className="text-sm text-ink-muted">
          One notification a day listing everything that&rsquo;s overdue, sent at
          this hour in your local time.
        </p>
        <ReminderSettingsForm profile={profile} />
      </section>
    </div>
  );
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { getOrCreateCareProfile } from "@/lib/plants/speciesCache";
import { isPlantType } from "@/lib/constants/plant-types";

export async function POST(request) {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) {
    return NextResponse.json({ error: "Not signed in." }, { status: 401 });
  }

  const body = await request.json();
  const scientificName = body.scientificName?.toString().trim();
  const commonName = body.commonName?.toString().trim() || null;
  const plantType = body.plantType?.toString();

  if (!scientificName) {
    return NextResponse.json({ error: "scientificName is required." }, { status: 400 });
  }
  if (!isPlantType(plantType)) {
    return NextResponse.json({ error: "Invalid plantType." }, { status: 400 });
  }

  try {
    const speciesCareProfile = await getOrCreateCareProfile(supabase, {
      scientificName,
      commonName,
      plantType,
    });
    return NextResponse.json({ speciesCareProfile });
  } catch (err) {
    return NextResponse.json({ error: err.message }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { createAdminClient } from "@/lib/supabase/admin";
import { sendNotification } from "@/lib/push/webPush";
import {
  localHourInTimezone,
  localDateInTimezone,
  buildDigestPayload,
} from "@/lib/push/digest";

// Triggered hourly by .github/workflows/push-digest.yml (Vercel Hobby only
// allows *daily* crons, and per-timezone delivery needs an hourly tick).
// Each run sends the digest only to users whose *local* hour currently equals
// their reminder_hour, so everyone gets it at their chosen time regardless of
// timezone.
//
// Idempotent per local day via profiles.last_digest_sent_on, so a retried or
// overlapping trigger can't send the same user two digests.
//
// Uses the service-role client: it deliberately reads across all users, which
// RLS would (correctly) forbid for a normal session.
export const dynamic = "force-dynamic";
export const maxDuration = 60;

function isAuthorized(request) {
  const secret = process.env.CRON_SECRET;
  if (!secret) return false;
  return request.headers.get("authorization") === `Bearer ${secret}`;
}

export async function GET(request) {
  if (!isAuthorized(request)) {
    return NextResponse.json({ error: "Unauthorized." }, { status: 401 });
  }

  const supabase = createAdminClient();
  const now = new Date();

  const { data: profiles, error: profilesError } = await supabase
    .from("profiles")
    .select("id, timezone, reminder_hour, last_digest_sent_on");
  if (profilesError) {
    return NextResponse.json({ error: profilesError.message }, { status: 500 });
  }

  const dueUsers = (profiles ?? []).filter((p) => {
    if (localHourInTimezone(p.timezone, now) !== p.reminder_hour) return false;
    // Already sent during this user's local day.
    const localDate = localDateInTimezone(p.timezone, now);
    return localDate !== null && p.last_digest_sent_on !== localDate;
  });

  let notified = 0;
  let skipped = 0;
  let pruned = 0;

  for (const profile of dueUsers) {
    const { data: overdueTasks, error: tasksError } = await supabase
      .from("care_tasks")
      .select("id, display_name, next_due_at, plants(nickname)")
      .eq("user_id", profile.id)
      .eq("is_paused", false)
      .lte("next_due_at", now.toISOString());

    if (tasksError || !overdueTasks || overdueTasks.length === 0) {
      skipped += 1;
      continue;
    }

    const { data: subscriptions } = await supabase
      .from("push_subscriptions")
      .select("id, endpoint, p256dh, auth")
      .eq("user_id", profile.id);

    if (!subscriptions || subscriptions.length === 0) {
      skipped += 1;
      continue;
    }

    const payload = buildDigestPayload(overdueTasks);
    let deliveredToAnyDevice = false;

    for (const subscription of subscriptions) {
      const result = await sendNotification(subscription, payload);
      if (result.ok) {
        notified += 1;
        deliveredToAnyDevice = true;
      } else if (result.gone) {
        // Push service says this endpoint is dead — drop it so it isn't
        // retried on every subsequent run.
        await supabase.from("push_subscriptions").delete().eq("id", subscription.id);
        pruned += 1;
      }
    }

    // Only mark the day as sent if something actually landed; a transient
    // push-service failure should be retried on the next hourly tick rather
    // than silently swallowing today's digest.
    if (deliveredToAnyDevice) {
      await supabase
        .from("profiles")
        .update({ last_digest_sent_on: localDateInTimezone(profile.timezone, now) })
        .eq("id", profile.id);
    }
  }

  return NextResponse.json({
    ok: true,
    checkedUsers: profiles?.length ?? 0,
    dueUsers: dueUsers.length,
    notified,
    skipped,
    pruned,
  });
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { identifySpecies, isSupportedImageType } from "@/lib/anthropic/identify";

const PHOTO_BUCKET = "plant-photos";
const MAX_BYTES = 8 * 1024 * 1024; // 8MB

export async function POST(request) {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) {
    return NextResponse.json({ error: "Not signed in." }, { status: 401 });
  }

  const formData = await request.formData();
  const photo = formData.get("photo");

  if (!photo || typeof photo === "string") {
    return NextResponse.json({ error: "No photo provided." }, { status: 400 });
  }
  if (!isSupportedImageType(photo.type)) {
    return NextResponse.json(
      { error: `Unsupported image type: ${photo.type}` },
      { status: 400 },
    );
  }
  if (photo.size > MAX_BYTES) {
    return NextResponse.json({ error: "Photo is too large (max 8MB)." }, { status: 400 });
  }

  const buffer = Buffer.from(await photo.arrayBuffer());
  const safeName = photo.name.replace(/[^a-zA-Z0-9._-]/g, "_");
  const photoPath = `${user.id}/uploads/${Date.now()}-${safeName}`;

  const { error: uploadError } = await supabase.storage
    .from(PHOTO_BUCKET)
    .upload(photoPath, buffer, { contentType: photo.type });
  if (uploadError) {
    return NextResponse.json(
      { error: `Photo upload failed: ${uploadError.message}` },
      { status: 500 },
    );
  }

  try {
    const result = await identifySpecies({
      base64: buffer.toString("base64"),
      mediaType: photo.type,
    });
    return NextResponse.json({ photoPath, ...result });
  } catch (err) {
    return NextResponse.json({ error: err.message }, { status: 502 });
  }
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { mutateOrThrow } from "@/lib/supabase/mutate";
import { isPlantType } from "@/lib/constants/plant-types";
import { isCareTaskType, defaultDisplayNameForTaskType } from "@/lib/constants/care-task-types";

export async function POST(request) {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) {
    return NextResponse.json({ error: "Not signed in." }, { status: 401 });
  }

  const body = await request.json();
  const nickname = body.nickname?.toString().trim();
  const photoPath = body.photoPath?.toString() || null;
  const speciesCareProfileId = body.speciesCareProfileId?.toString();
  const candidate = body.candidate;
  const tasks = Array.isArray(body.tasks) ? body.tasks : [];

  if (!nickname) {
    return NextResponse.json({ error: "Nickname is required." }, { status: 400 });
  }
  if (!candidate || !isPlantType(candidate.type) || !candidate.scientific_name) {
    return NextResponse.json({ error: "Invalid identified species." }, { status: 400 });
  }
  if (!speciesCareProfileId) {
    return NextResponse.json({ error: "Missing speciesCareProfileId." }, { status: 400 });
  }

  const validTasks = tasks
    .filter((t) => isCareTaskType(t.task_type) && Number.isInteger(t.interval_days) && t.interval_days > 0)
    .map((t) => ({
      task_type: t.task_type,
      display_name: defaultDisplayNameForTaskType(t.task_type),
      interval_days: t.interval_days,
      is_paused: Boolean(t.is_paused),
    }));

  let plantId;
  try {
    const plantRows = await mutateOrThrow(
      supabase.from("plants").insert({
        user_id: user.id,
        species_care_profile_id: speciesCareProfileId,
        nickname,
        plant_type: candidate.type,
        scientific_name: candidate.scientific_name,
        common_name: candidate.common_name || null,
        photo_path: photoPath,
        identification_confidence: candidate.confidence ?? null,
      }),
    );
    plantId = plantRows[0].id;

    if (validTasks.length > 0) {
      const now = Date.now();
      await mutateOrThrow(
        supabase.from("care_tasks").insert(
          validTasks.map((t) => ({
            plant_id: plantId,
            user_id: user.id,
            task_type: t.task_type,
            display_name: t.display_name,
            interval_days: t.interval_days,
            is_paused: t.is_paused,
            next_due_at: new Date(now + t.interval_days * 24 * 60 * 60 * 1000).toISOString(),
          })),
        ),
      );
    }
  } catch (err) {
    return NextResponse.json({ error: err.message }, { status: 500 });
  }

  return NextResponse.json({ plantId });
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";

export async function POST(request) {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) {
    return NextResponse.json({ error: "Not signed in." }, { status: 401 });
  }

  const body = await request.json();
  const endpoint = body.endpoint?.toString();
  const p256dh = body.keys?.p256dh?.toString();
  const auth = body.keys?.auth?.toString();

  if (!endpoint || !p256dh || !auth) {
    return NextResponse.json({ error: "Invalid subscription." }, { status: 400 });
  }

  // endpoint is UNIQUE — re-subscribing the same device (or a device that
  // changed hands) upserts rather than erroring.
  const { data, error } = await supabase
    .from("push_subscriptions")
    .upsert({ user_id: user.id, endpoint, p256dh, auth }, { onConflict: "endpoint" })
    .select();

  if (error) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
  if (!data || data.length === 0) {
    return NextResponse.json(
      { error: "Subscription write affected zero rows (RLS)." },
      { status: 500 },
    );
  }

  return NextResponse.json({ ok: true });
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";

export async function POST(request) {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) {
    return NextResponse.json({ error: "Not signed in." }, { status: 401 });
  }

  const body = await request.json();
  const endpoint = body.endpoint?.toString();
  if (!endpoint) {
    return NextResponse.json({ error: "Missing endpoint." }, { status: 400 });
  }

  // No zero-rows check here: unsubscribing a device that's already gone from
  // the table is the desired end state, not an error.
  const { error } = await supabase
    .from("push_subscriptions")
    .delete()
    .eq("endpoint", endpoint);

  if (error) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
  return NextResponse.json({ ok: true });
}

import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";

// Handles both the Google OAuth redirect and the magic-link redirect — both
// arrive here as a PKCE `code` to exchange for a session cookie.
export async function GET(request) {
  const { searchParams, origin } = new URL(request.url);
  const code = searchParams.get("code");
  const next = searchParams.get("next") ?? "/plants";

  if (code) {
    const supabase = await createClient();
    const { error } = await supabase.auth.exchangeCodeForSession(code);
    if (!error) {
      return NextResponse.redirect(`${origin}${next}`);
    }
  }

  return NextResponse.redirect(`${origin}/login?error=auth_callback_failed`);
}

