"use client";

import { useActionState, useEffect, useState } from "react";
import { FiCheck } from "react-icons/fi";
import { updateReminderSettingsAction } from "@/lib/profile/actions";

const initialState = { error: null, success: false };

const HOURS = Array.from({ length: 24 }, (_, h) => h);

function formatHour(hour) {
  const suffix = hour < 12 ? "AM" : "PM";
  const display = hour % 12 === 0 ? 12 : hour % 12;
  return `${display}:00 ${suffix}`;
}

export default function ReminderSettingsForm({ profile }) {
  const [state, formAction, pending] = useActionState(
    updateReminderSettingsAction,
    initialState,
  );

  const [detectedTz, setDetectedTz] = useState(null);
  const [timezone, setTimezone] = useState(profile.timezone);

  useEffect(() => {
    try {
      setDetectedTz(Intl.DateTimeFormat().resolvedOptions().timeZone);
    } catch {
      setDetectedTz(null);
    }
  }, []);

  return (
    <form action={formAction} className="space-y-4">
      <div className="card space-y-4 p-4">
        <div>
          <label
            htmlFor="reminder_hour"
            className="mb-1.5 block text-sm font-medium text-ink"
          >
            Send my digest at
          </label>
          <select
            id="reminder_hour"
            name="reminder_hour"
            defaultValue={profile.reminder_hour}
            className="field"
          >
            {HOURS.map((h) => (
              <option key={h} value={h}>
                {formatHour(h)}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label htmlFor="timezone" className="mb-1.5 block text-sm font-medium text-ink">
            Timezone
          </label>
          <input
            id="timezone"
            name="timezone"
            value={timezone}
            onChange={(e) => setTimezone(e.target.value)}
            className="field"
          />
          {detectedTz && detectedTz !== timezone && (
            <button
              type="button"
              onClick={() => setTimezone(detectedTz)}
              className="mt-2 text-xs font-medium text-brand underline underline-offset-2"
            >
              Use detected: {detectedTz}
            </button>
          )}
        </div>
      </div>

      {state.error && <p className="text-sm text-danger">{state.error}</p>}

      <div className="flex items-center gap-3">
        <button type="submit" disabled={pending} className="btn-primary">
          {pending ? "Saving..." : "Save"}
        </button>
        {state.success && !state.error && (
          <span className="flex items-center gap-1.5 text-sm text-brand">
            <FiCheck size={15} />
            Saved
          </span>
        )}
      </div>
    </form>
  );
}

import {
  getAnthropicClient,
  ANTHROPIC_MODEL,
  parseJsonResponse,
  extractText,
} from "@/lib/anthropic/client";
import { CARE_PROFILE_PROMPT } from "@/lib/anthropic/prompts";
import { isLightLevel, isHumidityLevel } from "@/lib/constants/care-profile-enums";

function validateCareProfile(profile) {
  const isNullableInt = (v) => v === null || Number.isInteger(v);

  if (
    !profile?.watering ||
    !Number.isInteger(profile.watering.interval_days_summer) ||
    !Number.isInteger(profile.watering.interval_days_winter)
  ) {
    throw new Error("Care profile missing valid watering intervals.");
  }
  if (
    !profile.fertilizing ||
    !Number.isInteger(profile.fertilizing.interval_days_growing_season) ||
    !isNullableInt(profile.fertilizing.interval_days_dormant)
  ) {
    throw new Error("Care profile missing valid fertilizing intervals.");
  }
  if (!profile.mist || !isNullableInt(profile.mist.interval_days)) {
    throw new Error("Care profile missing valid mist interval.");
  }
  if (!profile.light || !isLightLevel(profile.light.level)) {
    throw new Error("Care profile missing valid light level.");
  }
  if (!profile.humidity || !isHumidityLevel(profile.humidity.level)) {
    throw new Error("Care profile missing valid humidity level.");
  }
  if (
    !Array.isArray(profile.temperature_range_c) ||
    profile.temperature_range_c.length !== 2
  ) {
    throw new Error("Care profile missing valid temperature_range_c.");
  }
  if (!profile.toxicity || typeof profile.toxicity.pets !== "boolean") {
    throw new Error("Care profile missing valid toxicity.pets.");
  }
  if (!Array.isArray(profile.common_problems)) {
    throw new Error("Care profile missing common_problems.");
  }
  if (!Number.isInteger(profile.rotation_days)) {
    throw new Error("Care profile missing valid rotation_days.");
  }
  return profile;
}

export async function generateCareProfile({ scientificName, commonName }) {
  const client = getAnthropicClient();

  const speciesLabel = commonName
    ? `${scientificName} (${commonName})`
    : scientificName;

  const message = await client.messages.create({
    model: ANTHROPIC_MODEL,
    max_tokens: 1536,
    thinking: { type: "disabled" },
    system: CARE_PROFILE_PROMPT,
    messages: [{ role: "user", content: `Species: ${speciesLabel}` }],
  });

  const parsed = parseJsonResponse(extractText(message));
  return validateCareProfile(parsed);
}

import Anthropic from "@anthropic-ai/sdk";

let cachedClient = null;

export function getAnthropicClient() {
  if (!cachedClient) {
    cachedClient = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
  }
  return cachedClient;
}

// User-configured for this project via ANTHROPIC_AI_MODEL — an explicit
// choice, not a default we picked. Falls back to Sonnet 5 only if unset.
export const ANTHROPIC_MODEL = process.env.ANTHROPIC_AI_MODEL || "claude-sonnet-5";

// Strips accidental markdown fences before JSON.parse — the prompts already
// say "no code fences", this is just a defensive fallback.
export function parseJsonResponse(text) {
  const cleaned = text
    .trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/```\s*$/i, "")
    .trim();

  try {
    return JSON.parse(cleaned);
  } catch (err) {
    throw new Error(`Claude did not return valid JSON: ${err.message}`);
  }
}

export function extractText(message) {
  return message.content
    .filter((block) => block.type === "text")
    .map((block) => block.text)
    .join("");
}

import {
  getAnthropicClient,
  ANTHROPIC_MODEL,
  parseJsonResponse,
  extractText,
} from "@/lib/anthropic/client";
import { IDENTIFY_PROMPT } from "@/lib/anthropic/prompts";
import { isPlantType } from "@/lib/constants/plant-types";

const ALLOWED_MEDIA_TYPES = new Set([
  "image/jpeg",
  "image/png",
  "image/webp",
  "image/gif",
]);

export function isSupportedImageType(mediaType) {
  return ALLOWED_MEDIA_TYPES.has(mediaType);
}

function isCandidate(value) {
  return (
    value &&
    typeof value.common_name === "string" &&
    typeof value.scientific_name === "string" &&
    typeof value.confidence === "number" &&
    isPlantType(value.type)
  );
}

function validateIdentifyResult(result) {
  if (!result || !isCandidate(result.primary)) {
    throw new Error("Identification response missing a valid primary candidate.");
  }
  if (!Array.isArray(result.alternatives) || !result.alternatives.every(isCandidate)) {
    throw new Error("Identification response has invalid alternatives.");
  }
  if (!Array.isArray(result.visible_health_issues)) {
    result.visible_health_issues = [];
  }
  return result;
}

export async function identifySpecies({ base64, mediaType }) {
  const client = getAnthropicClient();

  const message = await client.messages.create({
    model: ANTHROPIC_MODEL,
    max_tokens: 1024,
    thinking: { type: "disabled" },
    system: IDENTIFY_PROMPT,
    messages: [
      {
        role: "user",
        content: [
          {
            type: "image",
            source: { type: "base64", media_type: mediaType, data: base64 },
          },
          { type: "text", text: "Identify this plant." },
        ],
      },
    ],
  });

  const parsed = parseJsonResponse(extractText(message));
  return validateIdentifyResult(parsed);
}

"use server";

import { revalidatePath } from "next/cache";
import { createClient } from "@/lib/supabase/server";
import { mutateOrThrow } from "@/lib/supabase/mutate";

async function requireUser(supabase) {
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) throw new Error("Not signed in.");
  return user;
}

// Feature spec: "mark done rolls next_due_at forward by interval_days" — a
// fixed-schedule roll-forward from the task's *existing* next_due_at, not
// from now(). If a task was very overdue, marking it done advances the
// schedule by exactly one interval rather than snapping to "next occurrence
// after today" — matches the literal spec; revisit if that's not the
// intended behavior.
export async function markTaskDoneAction(taskId, plantId) {
  const supabase = await createClient();
  await requireUser(supabase);

  const { data: task, error } = await supabase
    .from("care_tasks")
    .select("interval_days, next_due_at")
    .eq("id", taskId)
    .maybeSingle();
  if (error) throw new Error(error.message);
  if (!task) throw new Error("Task not found.");

  const newNextDueAt = new Date(
    new Date(task.next_due_at).getTime() + task.interval_days * 24 * 60 * 60 * 1000,
  ).toISOString();

  await mutateOrThrow(
    supabase
      .from("care_tasks")
      .update({ next_due_at: newNextDueAt, last_completed_at: new Date().toISOString() })
      .eq("id", taskId),
  );

  revalidatePath(`/plants/${plantId}`);
}

export async function updateTaskIntervalAction(taskId, plantId, intervalDays) {
