  await mutateOrThrow(
    supabase.from("care_tasks").update({ interval_days: intervalDays }).eq("id", taskId),
  );

  revalidatePath(`/plants/${plantId}`);
}

export async function toggleTaskPauseAction(taskId, plantId, isPaused) {
