}

export async function addCustomTaskAction(_prevState, formData) {
  const supabase = await createClient();
  const plantId = formData.get("plant_id")?.toString();
  const displayName = formData.get("display_name")?.toString().trim();
  const intervalDays = Number(formData.get("interval_days"));

  try {
    const user = await requireUser(supabase);
    if (!plantId) throw new Error("Missing plant id.");
    if (!displayName) throw new Error("Task name is required.");
    if (!Number.isInteger(intervalDays) || intervalDays <= 0) {
      throw new Error("Interval must be a positive whole number of days.");
    }

    await mutateOrThrow(
      supabase.from("care_tasks").insert({
        plant_id: plantId,
        user_id: user.id,
        task_type: "custom",
        display_name: displayName,
        interval_days: intervalDays,
        next_due_at: new Date(Date.now() + intervalDays * 24 * 60 * 60 * 1000).toISOString(),
        is_paused: false,
      }),
    );
  } catch (err) {
    return { error: err.message };
  }

  revalidatePath(`/plants/${plantId}`);
  return { error: null, success: true };
}

const MS_PER_DAY = 24 * 60 * 60 * 1000;

// Returns { label, tone } describing when a task is next due, for display
// only — doesn't affect scheduling. tone is one of "paused" | "overdue" |
// "soon" | "ok" (for styling hooks in the UI layer).
export function getDueStatus(task) {
  if (task.is_paused) {
    return { label: "Paused", tone: "paused" };
  }

  const diffDays = Math.round(
    (new Date(task.next_due_at).getTime() - Date.now()) / MS_PER_DAY,
  );

  if (diffDays < 0) {
    return {
      label: `Overdue by ${Math.abs(diffDays)} day${Math.abs(diffDays) === 1 ? "" : "s"}`,
      tone: "overdue",
    };
  }
  if (diffDays === 0) {
    return { label: "Due today", tone: "soon" };
  }
  if (diffDays === 1) {
    return { label: "Due tomorrow", tone: "soon" };
  }
  return { label: `Due in ${diffDays} days`, tone: "ok" };
}

export async function getCareTasksForPlant(supabase, plantId) {
