"use server";

import { redirect } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { mutateOrThrow } from "@/lib/supabase/mutate";
import { isPlantType } from "@/lib/constants/plant-types";

const PHOTO_BUCKET = "plant-photos";

async function requireUser(supabase) {
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) throw new Error("Not signed in.");
  return user;
}

function readPlantFields(formData) {
  const nickname = formData.get("nickname")?.toString().trim() ?? "";
  const plantType = formData.get("plant_type")?.toString() ?? "";
  const notes = formData.get("notes")?.toString().trim() || null;

  if (!nickname) throw new Error("Nickname is required.");
  if (!isPlantType(plantType)) throw new Error("Invalid plant type.");

  return { nickname, plant_type: plantType, notes };
}

async function uploadPhotoIfPresent(supabase, userId, plantId, formData) {
  const photo = formData.get("photo");
  if (!photo || typeof photo === "string" || photo.size === 0) return null;

  const safeName = photo.name.replace(/[^a-zA-Z0-9._-]/g, "_");
  const path = `${userId}/${plantId}/${Date.now()}-${safeName}`;

  const { error } = await supabase.storage
    .from(PHOTO_BUCKET)
    .upload(path, photo, { contentType: photo.type });
  if (error) throw new Error(`Photo upload failed: ${error.message}`);

  return path;
}

// Plant creation goes through the AI identify -> care profile wizard
// (src/components/plants/AddPlantWizard.js -> /api/identify, /api/care-profile,
// /api/plants) instead of a plain form/server action — nickname and category
// are derived from Claude's identification, not typed in upfront. This
// action only covers editing an already-created plant (e.g. to correct a
// misidentified category, rename, or replace the photo).
export async function updatePlantAction(_prevState, formData) {
  const supabase = await createClient();
  const plantId = formData.get("id")?.toString();
  if (!plantId) return { error: "Missing plant id." };

  try {
    const user = await requireUser(supabase);
    const fields = readPlantFields(formData);

    const photoPath = await uploadPhotoIfPresent(
      supabase,
      user.id,
      plantId,
      formData,
    );

    await mutateOrThrow(
      supabase
        .from("plants")
        .update({ ...fields, ...(photoPath ? { photo_path: photoPath } : {}) })
        .eq("id", plantId),
    );
  } catch (err) {
    return { error: err.message };
  }

  redirect(`/plants/${plantId}`);
}

export async function deletePlantAction(plantId) {
  const supabase = await createClient();
  await requireUser(supabase);

  const { data: plant } = await supabase
    .from("plants")
    .select("photo_path")
    .eq("id", plantId)
    .maybeSingle();

  await mutateOrThrow(supabase.from("plants").delete().eq("id", plantId));

  if (plant?.photo_path) {
    // Best-effort cleanup — a failed storage delete shouldn't block the
    // plant record (and its care_tasks, via ON DELETE CASCADE) from being gone.
    await supabase.storage.from(PHOTO_BUCKET).remove([plant.photo_path]);
  }

  redirect("/plants");
}

import { defaultDisplayNameForTaskType } from "@/lib/constants/care-task-types";

// Derives the default editable task list from a Claude-generated care
// profile. The profile has *seasonal* intervals (summer/winter,
// growing-season/dormant); care_tasks only has one interval_days each, so
// this picks the summer/growing-season value as the starting point — see
// "Seeding care_tasks from a generated care profile" in CLAUDE.md.
export function deriveTasksFromCareProfile(careProfile) {
  const tasks = [];

  if (Number.isInteger(careProfile?.watering?.interval_days_summer)) {
    tasks.push({
      task_type: "watering",
      display_name: defaultDisplayNameForTaskType("watering"),
      interval_days: careProfile.watering.interval_days_summer,
      is_paused: false,
    });
  }

  if (Number.isInteger(careProfile?.fertilizing?.interval_days_growing_season)) {
    tasks.push({
      task_type: "fertilizing",
      display_name: defaultDisplayNameForTaskType("fertilizing"),
      interval_days: careProfile.fertilizing.interval_days_growing_season,
      is_paused: false,
    });
  }

  if (Number.isInteger(careProfile?.mist?.interval_days)) {
    tasks.push({
      task_type: "misting",
      display_name: defaultDisplayNameForTaskType("misting"),
      interval_days: careProfile.mist.interval_days,
      is_paused: false,
    });
  }

  if (careProfile?.rotation_days > 0) {
    tasks.push({
      task_type: "rotating",
      display_name: defaultDisplayNameForTaskType("rotating"),
      interval_days: careProfile.rotation_days,
      is_paused: false,
    });
  }

  return tasks;
}

const PHOTO_BUCKET = "plant-photos";
const SIGNED_URL_TTL_SECONDS = 60 * 60; // 1 hour — regenerated on every page load

// Attaches a `photo_url` (signed, or null) to each plant. Batches all photo
// paths into a single createSignedUrls() call instead of one request per plant.
async function withSignedPhotoUrls(supabase, plants) {
  const paths = plants.map((p) => p.photo_path).filter(Boolean);
  if (paths.length === 0) {
    return plants.map((p) => ({ ...p, photo_url: null }));
  }

  const { data: signed, error } = await supabase.storage
    .from(PHOTO_BUCKET)
    .createSignedUrls(paths, SIGNED_URL_TTL_SECONDS);

  if (error) {
    // Missing/broken photos shouldn't take down the whole list page.
    return plants.map((p) => ({ ...p, photo_url: null }));
  }

  const urlByPath = new Map(signed.map((s) => [s.path, s.signedUrl]));
  return plants.map((p) => ({
    ...p,
    photo_url: p.photo_path ? (urlByPath.get(p.photo_path) ?? null) : null,
  }));
}

export async function getPlantsForUser(supabase, { plantType } = {}) {
  let query = supabase
    .from("plants")
    .select(
      "id, nickname, plant_type, scientific_name, common_name, photo_path, created_at",
    )
    .order("created_at", { ascending: false });

  if (plantType) {
    query = query.eq("plant_type", plantType);
  }

  const { data, error } = await query;
  if (error) throw new Error(error.message);

  const plants = await withSignedPhotoUrls(supabase, data ?? []);
  return withOverdueCounts(supabase, plants);
}

// Attaches `overdue_count` to each plant so the list can badge plants that
// need attention. One query for all of the user's due tasks (RLS already
// scopes it to them), tallied in memory — not one query per plant.
async function withOverdueCounts(supabase, plants) {
  if (plants.length === 0) return plants;

  const { data, error } = await supabase
    .from("care_tasks")
    .select("plant_id")
    .eq("is_paused", false)
    .lte("next_due_at", new Date().toISOString());

  if (error) {
    return plants.map((p) => ({ ...p, overdue_count: 0 }));
  }

  const counts = new Map();
  for (const row of data ?? []) {
    counts.set(row.plant_id, (counts.get(row.plant_id) ?? 0) + 1);
  }
  return plants.map((p) => ({ ...p, overdue_count: counts.get(p.id) ?? 0 }));
}

// Counts per plant_type for the current user, used to render tab badges.
export async function getPlantTypeCounts(supabase) {
  const { data, error } = await supabase.from("plants").select("plant_type");
  if (error) throw new Error(error.message);

  const counts = {};
  for (const row of data ?? []) {
    counts[row.plant_type] = (counts[row.plant_type] ?? 0) + 1;
  }
  return counts;
}

export async function getPlantById(supabase, id) {
  const { data, error } = await supabase
    .from("plants")
    .select(
      "id, nickname, plant_type, scientific_name, common_name, photo_path, notes, identification_confidence, created_at, updated_at",
    )
    .eq("id", id)
    .maybeSingle();

  if (error) throw new Error(error.message);
  if (!data) return null;

  const [withUrl] = await withSignedPhotoUrls(supabase, [data]);
  return withUrl;
}

import { generateCareProfile } from "@/lib/anthropic/careProfile";

export function normalizeScientificName(scientificName) {
  return scientificName.trim().toLowerCase();
}

// Returns the cached species_care_profiles row for this species, generating
// (and caching) one via Claude if it doesn't exist yet — so the same species
// is never regenerated across users.
export async function getOrCreateCareProfile(
  supabase,
  { scientificName, commonName, plantType },
) {
  const key = normalizeScientificName(scientificName);

  const { data: existing, error: lookupError } = await supabase
    .from("species_care_profiles")
    .select("id, scientific_name, common_name, plant_type, care_profile")
    .eq("scientific_name_key", key)
    .maybeSingle();

  if (lookupError) throw new Error(lookupError.message);
  if (existing) return existing;

  const careProfile = await generateCareProfile({ scientificName, commonName });

  const { data: inserted, error: insertError } = await supabase
    .from("species_care_profiles")
    .insert({
      scientific_name_key: key,
      scientific_name: scientificName,
      common_name: commonName || null,
      plant_type: plantType,
      care_profile: careProfile,
    })
    .select();

  if (insertError) {
    // Another concurrent request cached the same species first (unique
    // violation on scientific_name_key) — reuse its row instead of failing.
    if (insertError.code === "23505") {
      const { data: raceWinner, error: refetchError } = await supabase
        .from("species_care_profiles")
        .select("id, scientific_name, common_name, plant_type, care_profile")
        .eq("scientific_name_key", key)
        .single();
      if (refetchError) throw new Error(refetchError.message);
      return raceWinner;
    }
    throw new Error(insertError.message);
  }
  if (!inserted || inserted.length === 0) {
    throw new Error(
      "Write affected zero rows — the row may not exist, or Row Level Security denied it.",
    );
  }

  return inserted[0];
}

"use server";

import { revalidatePath } from "next/cache";
import { createClient } from "@/lib/supabase/server";
import { mutateOrThrow } from "@/lib/supabase/mutate";

export async function updateReminderSettingsAction(_prevState, formData) {
  const supabase = await createClient();

  const reminderHour = Number(formData.get("reminder_hour"));
  const timezone = formData.get("timezone")?.toString().trim();

  try {
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) throw new Error("Not signed in.");

    if (!Number.isInteger(reminderHour) || reminderHour < 0 || reminderHour > 23) {
      throw new Error("Reminder hour must be between 0 and 23.");
    }
    if (!timezone) throw new Error("Timezone is required.");
    // Reject anything Intl doesn't recognize — the cron digest resolves each
    // user's local hour with this string, so a bad value would silently
    // exclude them from every digest.
    try {
      new Intl.DateTimeFormat("en-US", { timeZone: timezone });
    } catch {
      throw new Error(`Unrecognized timezone: ${timezone}`);
    }

    await mutateOrThrow(
      supabase
        .from("profiles")
        .update({ reminder_hour: reminderHour, timezone })
        .eq("id", user.id),
    );
  } catch (err) {
    return { error: err.message };
  }

  revalidatePath("/settings");
  return { error: null, success: true };
}

// Returns the current local hour (0-23) in the given IANA timezone.
// Returns null for an unrecognized timezone rather than throwing, so one bad
// profile row can't abort the whole cron run.
export function localHourInTimezone(timezone, now = new Date()) {
  try {
    const hour = new Intl.DateTimeFormat("en-US", {
      timeZone: timezone,
      hour: "numeric",
      hour12: false,
    }).format(now);
    const parsed = Number(hour);
    // hour12:false can render midnight as "24" in some ICU versions.
    return parsed === 24 ? 0 : parsed;
  } catch {
    return null;
  }
}

// Returns the current local date in the given IANA timezone as YYYY-MM-DD
// (matching a Postgres `date`). Null for an unrecognized timezone.
export function localDateInTimezone(timezone, now = new Date()) {
  try {
    // en-CA renders as YYYY-MM-DD.
    return new Intl.DateTimeFormat("en-CA", {
      timeZone: timezone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).format(now);
  } catch {
    return null;
  }
}

export function buildDigestPayload(overdueTasks) {
  const count = overdueTasks.length;
  const plantNames = [...new Set(overdueTasks.map((t) => t.plants?.nickname).filter(Boolean))];

  const body =
    count === 1
      ? `${overdueTasks[0].display_name} for ${overdueTasks[0].plants?.nickname ?? "a plant"}`
      : `${count} tasks across ${plantNames.length} plant${plantNames.length === 1 ? "" : "s"}: ${plantNames.slice(0, 3).join(", ")}${plantNames.length > 3 ? "…" : ""}`;

  return {
    title: count === 1 ? "1 plant needs attention" : `${count} plant tasks are due`,
    body,
    tag: "plant-care-digest",
    url: "/plants",
  };
}

// Browser-side helpers for the Push API. Kept out of the component so the
// base64 conversion and the SW-registration dance are testable/reusable.

export function isPushSupported() {
  return (
    typeof window !== "undefined" &&
    "serviceWorker" in navigator &&
    "PushManager" in window &&
    "Notification" in window
  );
}

// VAPID public keys are base64url; PushManager wants a Uint8Array.
function urlBase64ToUint8Array(base64String) {
  const padding = "=".repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, "+").replace(/_/g, "/");
  const raw = window.atob(base64);
  return Uint8Array.from([...raw].map((c) => c.charCodeAt(0)));
}

// `navigator.serviceWorker.ready` NEVER settles when no service worker is
// registered — it isn't rejected, it just hangs. In `next dev` Serwist is
// skipped entirely, so awaiting it there makes the subscribe button spin
// forever with no error. Always go through this helper, which resolves to
// null instead of hanging.
export async function getActiveRegistration({ timeoutMs = 6000 } = {}) {
  if (!isPushSupported()) return null;

  const existing = await navigator.serviceWorker.getRegistration();
  if (existing?.active) return existing;

  return Promise.race([
    navigator.serviceWorker.ready,
    new Promise((resolve) => setTimeout(() => resolve(null), timeoutMs)),
  ]);
}

const NO_SERVICE_WORKER_MESSAGE =
  "No service worker is running, so notifications can't be enabled. There is no service worker in `npm run dev` — build and start the app (`npm run build && npm start`) to test push.";

export async function getExistingSubscription() {
  if (!isPushSupported()) return null;
  const registration = await navigator.serviceWorker.getRegistration();
  if (!registration) return null;
  return registration.pushManager.getSubscription();
}

export async function subscribeToPush() {
  if (!isPushSupported()) {
    throw new Error("Push notifications aren't supported in this browser.");
  }
  if (!process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY) {
    throw new Error("NEXT_PUBLIC_VAPID_PUBLIC_KEY isn't set in this build.");
  }

  // Check for the service worker BEFORE prompting: otherwise we burn the
  // one-shot permission prompt and then fail anyway.
  const registration = await getActiveRegistration();
  if (!registration) {
    throw new Error(NO_SERVICE_WORKER_MESSAGE);
  }

  const permission = await Notification.requestPermission();
  if (permission === "denied") {
    throw new Error(
      "Notifications are blocked for this site. Enable them in your browser's site settings, then try again.",
    );
  }
  if (permission !== "granted") {
    throw new Error("Notification permission wasn't granted.");
  }

  // Reuse an existing subscription if the browser already has one for this
  // registration — calling subscribe() twice with a different key throws.
  let subscription = await registration.pushManager.getSubscription();
  if (!subscription) {
    subscription = await registration.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: urlBase64ToUint8Array(
        process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY,
      ),
    });
  }

  const res = await fetch("/api/push/subscribe", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(subscription.toJSON()),
  });
  if (!res.ok) {
    const data = await res.json().catch(() => ({}));
    throw new Error(data.error || "Couldn't save the subscription.");
  }

  return subscription;
}

export async function unsubscribeFromPush() {
  const subscription = await getExistingSubscription();
  if (!subscription) return;

  await fetch("/api/push/unsubscribe", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ endpoint: subscription.endpoint }),
  });
  await subscription.unsubscribe();
}

import webpush from "web-push";

let configured = false;

// VAPID keys were generated with `npx web-push generate-vapid-keys` and live
// in .env.local (NEXT_PUBLIC_VAPID_PUBLIC_KEY / VAPID_PRIVATE_KEY).
export function getWebPush() {
  if (!configured) {
    webpush.setVapidDetails(
      process.env.VAPID_SUBJECT || "mailto:admin@example.com",
      process.env.NEXT_PUBLIC_VAPID_PUBLIC_KEY,
      process.env.VAPID_PRIVATE_KEY,
    );
    configured = true;
  }
  return webpush;
}

// Sends one notification. Returns { ok, gone } — `gone` means the push
// service reported the subscription is dead (404/410), so the caller should
// delete that row rather than retrying it forever.
export async function sendNotification(subscription, payload) {
  try {
    await getWebPush().sendNotification(
      {
        endpoint: subscription.endpoint,
        keys: { p256dh: subscription.p256dh, auth: subscription.auth },
      },
      JSON.stringify(payload),
    );
    return { ok: true, gone: false };
  } catch (err) {
    const gone = err.statusCode === 404 || err.statusCode === 410;
    return { ok: false, gone, error: err.message };
  }
}

import { createClient as createSupabaseClient } from "@supabase/supabase-js";

// Privileged server-only client (service role / secret key — bypasses RLS).
// NEVER import this from client components or expose the key to the browser.
// Reserved for trusted server-side jobs (e.g. the push-digest cron route)
// that legitimately need to read/write across all users.
export function createAdminClient() {
  return createSupabaseClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL,
    process.env.SUPABASE_SERVICE_ROLE_KEY,
    {
      auth: { autoRefreshToken: false, persistSession: false },
    },
  );
}

import { createBrowserClient } from "@supabase/ssr";

// Browser-side Supabase client (uses the publishable/anon key — safe to expose).
export function createClient() {
  return createBrowserClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
  );
}

// Supabase .insert()/.update()/.delete() on an RLS-filtered row returns
// success with zero rows if the policy denies the write — no thrown error.
// Every write in this codebase goes through this helper: always chain
// .select() and treat an empty result as an error, never trust the absence
// of `error` alone.
export async function mutateOrThrow(builder, { allowEmpty = false } = {}) {
  const { data, error } = await builder.select();

  if (error) {
    throw new Error(error.message);
  }
  if (!allowEmpty && (!data || data.length === 0)) {
    throw new Error(
      "Write affected zero rows — the row may not exist, or Row Level Security denied it.",
    );
  }
  return data;
}

import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";

// Server-side Supabase client for Server Components, Route Handlers, and
// Server Actions. Reads/writes the auth cookies via next/headers.
export async function createClient() {
  const cookieStore = await cookies();

  return createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
    {
      cookies: {
        getAll() {
          return cookieStore.getAll();
        },
        setAll(cookiesToSet) {
          try {
            cookiesToSet.forEach(({ name, value, options }) =>
              cookieStore.set(name, value, options),
            );
          } catch {
            // Called from a Server Component — the middleware refreshes the
            // session on every request, so this can be safely ignored.
          }
        },
      },
    },
  );
}

import { createServerClient } from "@supabase/ssr";
import { NextResponse } from "next/server";

const PUBLIC_PATHS = ["/login", "/auth/callback", "/offline"];

function isPublicPath(pathname) {
  if (PUBLIC_PATHS.includes(pathname)) return true;
  // API routes authenticate themselves and return a JSON 401 — they must NOT
  // be redirected to /login here. Two reasons: (1) /api/cron/push-digest is
  // called by Vercel Cron with a CRON_SECRET bearer token and no session
  // cookie, so a redirect would silently stop every digest from ever
  // running; (2) a redirect turns a fetch()'s expected JSON 401 into a 307
  // to an HTML page, which the client can't parse.
  if (pathname.startsWith("/api/")) return true;
  // Next.js internals, static assets, and PWA files must stay unauthenticated.
  if (pathname.startsWith("/_next")) return true;
  if (pathname === "/manifest.webmanifest") return true;
  if (pathname === "/sw.js") return true;
  if (pathname.startsWith("/icons")) return true;
  if (pathname === "/favicon.ico") return true;
  return false;
}

export async function proxy(request) {
  let response = NextResponse.next({ request });

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll();
        },
        setAll(cookiesToSet) {
          cookiesToSet.forEach(({ name, value }) =>
            request.cookies.set(name, value),
          );
          response = NextResponse.next({ request });
          cookiesToSet.forEach(({ name, value, options }) =>
            response.cookies.set(name, value, options),
          );
        },
      },
    },
  );

  // Required: this call refreshes the session and must not be skipped.
  const {
    data: { user },
  } = await supabase.auth.getUser();

  const { pathname } = request.nextUrl;

  if (!user && !isPublicPath(pathname)) {
    const redirectUrl = new URL("/login", request.url);
    redirectUrl.searchParams.set("next", pathname);
    return NextResponse.redirect(redirectUrl);
  }

  if (user && pathname === "/login") {
    return NextResponse.redirect(new URL("/plants", request.url));
  }

  return response;
}

export const config = {
  matcher: [
    "/((?!_next/static|_next/image|favicon.ico|manifest.webmanifest|sw.js|icons).*)",
  ],
};
